  ctx.tools.register({
    name: 'memory_remember',
    description:
      '保存一条跨会话记忆（reasonix 与 dsh 共用同一份语料，写进去两端都读得到）。完成「下次还记得」的操作后调用：装/卸软件、改配置或 key 位置、批量文件操作（>5 个文件）、项目结构变更、排障定论、用户明确偏好。同 name 视为同一条并 upsert（revision +1）。若正文里有会过期的状态，请写明「截至日期」。',
    parameters: toJsonSchema({
      name: { type: 'string', required: true, description: '事实名：kebab-case 或简短中文名，作为文件名；同名即更新同一条' },
      description: { type: 'string', required: true, description: '一句话说清存了什么（进索引）' },
      body: { type: 'string', required: true, description: 'Markdown 正文：关键事实，让未来的会话不用重新推导' },
      factType: { type: 'string', description: 'reference（工具/配置）| project（项目）| feedback（规则）| user（画像），默认 reference' },
      scope: { type: 'string', description: 'global（默认）| project' },
    }),
    output: {
      schema: { type: 'object', additionalProperties: false, properties: { text: { type: 'string' } }, required: ['text'] },
      render: (_a, v) => [{ type: 'text', text: v.text }],
    },
    async execute(args) {
      const scope = String(args.scope ?? 'global').trim()
      if (!SCOPES.includes(scope)) return { text: `scope 必须是 ${SCOPES.join(' 或 ')}。` }
      const factName = sanitizeName(String(args.name ?? ''))
      if (factName.length === 0) return { text: 'name 不能为空。' }
      const body = String(args.body ?? '').trim()
      if (body.length === 0) return { text: 'body 不能为空。' }

      const dir = join(MEMORY_ROOT, scope)
      await mkdir(dir, { recursive: true })
      const file = join(dir, `${factName}.md`)

      let previous
      try {
        previous = parseFact(await readFile(file, 'utf8'))
      } catch {
        previous = undefined
      }

      const now = new Date().toISOString()
      const meta = previous?.meta ?? {}
      const factType = String(args.factType ?? meta.fact_type ?? 'reference').trim() || 'reference'
      const description = String(args.description ?? meta.description ?? '').replace(/\s+/g, ' ').trim() || factName
      const fact = renderFact({
        id: meta.id || `mem-${randomBytes(16).toString('hex')}`,
        revision: previous === undefined ? 1 : (Number(meta.revision) || 1) + 1,
        createdAt: meta.created_at || now,
        updatedAt: now,
        name: factName,
        description,
        factType,
        scope,
        body,
      })
      await atomicWrite(file, fact)
      const index = await upsertIndexEntry(scope, factName, description)
      const verb = previous === undefined ? 'Saved' : 'Updated'
      return { text: `${verb} memory "${factName}" (revision ${Number(meta.revision) || 0 || 1}, scope ${scope})\nfile: ${file}\nindex: ${index.message}` }
    },
  })
}
```

