    let info
    try {
      info = await stat(file)
    } catch {
      continue
    }
    const stamp = `${Math.round(info.mtimeMs)}:${info.size}`
    const known = index.sessions[file]
    if (!force && known && known.stamp === stamp) {
      reused++
      continue
