export function apply(ctx) {
  ctx.tools.register({
    name: 'session_index',
    description:
      '跨 cwd 列出本机全部 dsh 会话（id / cwd / 首条用户消息 / 时间 / 大小），用于回答「我上次在做什么」「那批批量任务派发了哪些子会话」。默认按时间倒序返回最近 30 条，只读，不修改任何会话数据。要按内容搜索会话正文请用 session-query 工具。',
    parameters: toJsonSchema({
      query: { type: 'string', description: '可选：关键词，匹配 cwd 或首条用户消息' },
      cwd: { type: 'string', description: '可选：只看某个 cwd（子串匹配）' },
      since: { type: 'string', description: '可选：时间窗，如 3d / 12h / 2w（按文件修改时间）' },
      limit: { type: 'string', description: '可选：返回条数，默认 30' },
      refresh: { type: 'string', description: '可选：传 "1" 强制全量重扫（默认增量）' },
    }),
    output: { schema: {...}, render: ... },
    async execute(args) {
      const wantRefresh = String(args.refresh ?? '') === '1'
      const { index, files, updated, reused } = await refresh(wantRefresh)
      const records = Object.values(index.sessions)
      const query = String(args.query ?? '').toLowerCase().trim()
      const cwdFilter = String(args.cwd ?? '').toLowerCase().trim()
      const windowMs = parseWindow(args.since)
      const limit = Math.min(Math.max(Number(args.limit) || MAX_RESULTS, 1), 200)

      const filtered = records.filter((r) => {
        if (cwdFilter && !String(r.cwd).toLowerCase().includes(cwdFilter)) return false
        if (windowMs && Date.now() - (r.mtimeMs ?? 0) > windowMs) return false
        if (query) {
          const hay = `${r.title} ${r.cwd} ${r.id}`.toLowerCase()
          if (!hay.includes(query)) return false
        }
        return true
      })
      filtered.sort((a, b) => (b.mtimeMs ?? 0) - (a.mtimeMs ?? 0))
      const shown = filtered.slice(0, limit)
      if (shown.length === 0) {
        return { text: `No session matches (${records.length} indexed, ${files} files scanned).` }
      }
      const lines = shown.map((r) => {
        const when = new Date(r.mtimeMs ?? 0).toISOString().slice(5, 16).replace('T', ' ')
        const size = `${Math.round((r.bytes ?? 0) / 1024)}K`
        const cwd = String(r.cwd || '?').replace(/^[A-Za-z]:/, '').slice(0, 26)
        const title = r.title || '(no user message)'
        return `${when} ${size.padStart(6)} v${r.version} ${cwd.padEnd(27)} ${title}  [${String(r.id).slice(0, 18)}]`
      })
      const head = `Sessions (${filtered.length} matched / ${records.length} indexed; ${updated} rescanned, ${reused} cached):`
      return { text: `${head}\n${lines.join('\n')}` }
    },
  })
}

/** Parse a window like 3d / 12h / 2w into milliseconds. */
function parseWindow(raw) {
  const text = String(raw ?? '').trim().toLowerCase()
  const match = /^(\d+)\s*([hdwm])$/.exec(text)
  if (!match) return 0
  const n = Number(match[1])
  const unit = { h: 3600e3, d: 86400e3, w: 604800e3, m: 2592e6 }[match[2]]
  return n * unit
}
