async function digestSession(file) {
  const buffer = await readFile(file)
  const offsets = frameOffsets(buffer)
  const dec = (i) => { try { return zstdDecompressSync(buffer.subarray(offsets[i], offsets[i+1] ?? buffer.length)).toString('utf8') } catch { return '' } }
  const frameCount = offsets.length
  let header = {}
  let firstUser = ''
  let toolCalls = 0
  let errors = 0
  let maxTurn = 0
  let lastAssistant = ''
  // header + first user: first frames
  for (let i = 0; i < Math.min(frameCount, 8); i++) {
    const text = dec(i)
    if (i === 0) { try { const p = JSON.parse(text.split('\n')[0]); if (p?.type === 'session') header = p } catch {} }
    if (firstUser === '' && text.includes('user/message')) firstUser = firstUserText(text)
  }
  // totals: every frame
  for (let i = 0; i < frameCount; i++) {
    const text = dec(i)
    toolCalls += (text.match(/"type":"tool\/result"/g) || []).length
    errors += (text.match(/"isError":true/g) || []).length
    const turns = text.match(/"turn":(\d+)/g)
    if (turns) for (const t of turns) { const n = Number(t.slice(7)); if (n > maxTurn) maxTurn = n }
  }
  // conclusion: last frames
  for (let i = frameCount - 1; i >= Math.max(0, frameCount - 8); i--) {
    const text = dec(i)
    if (!text.includes('assistant/message')) continue
    const lines = text.split('\n')
    for (let k = lines.length - 1; k >= 0; k--) {
      if (!lines[k].includes('assistant/message')) continue
      try {
        const e = JSON.parse(lines[k])
        const parts = e.data?.message?.content ?? []
        const t = parts.filter(p => p?.type === 'text').map(p => p.text).join(' ').replace(/\s+/g, ' ').trim()
        if (t) { lastAssistant = t.slice(0, 600); break }
      } catch {}
    }
    if (lastAssistant) break
  }
  return { header, firstUser, toolCalls, errors, maxTurn, lastAssistant, frameCount, bytes: buffer.length }
}
```

