async function saveBudgets(state) {
  await mkdir(dirname(BUDGET_PATH), { recursive: true })
  const tmp = `${BUDGET_PATH}.tmp-${process.pid}`
  await writeFile(tmp, JSON.stringify(state, null, 1), 'utf8')
  await rename(tmp, BUDGET_PATH)
}

