function spentOf(acc) {
  if (!acc) return 0
  return (acc.input ?? 0) + (acc.output ?? 0)
}

/** Session override beats the default budget. */
function effectiveBudget(state, sessionId) {
  return state.sessions?.[sessionId] ?? state.default ?? null
}

