  },
}))
process.env.DSH_SKILL_USAGE = ledger

const { apply } = await import('./.agent-presets/anchored-standard/skill-search.mjs')
const reg = []
const injected = []
const fakeSkills = {
  list: async () => [
    { name: 'bilingual-translator', description: '翻译 PDF/DOCX 成行内双语 Markdown' },
    { name: 'bilingual-ocw-translator', description: '翻译 MIT OCW 讲义流水线' },
    { name: 'pdf', description: 'PDF 解析与生成' },
  ],
  get: async (name) => (name.includes('bilingual') ? { name, content: '# body of ' + name } : undefined),
}
apply({ tools: { register: (t) => reg.push(t) }, skills: fakeSkills })
const search = reg.find((t) => t.name === 'skill_search')
const load = reg.find((t) => t.name === 'skill_load')
const agent = { session: { header: { cwd: 'C:/x' } }, inject: (m) => injected.push(m) }

console.log('=== 1. 搜索结果（应带使用标记，且 20 次的排前）===')
console.log((await search.execute({ query: '翻译' }, { agent })).text)

console.log('\n=== 2. 调 skill_load 一次 → 应累加账本 ===')
