console.log('\n=== 3. 再搜（pdf 与翻译不匹配，应仍只出两条）===')
const r3 = await search.execute({ query: '翻译' }, { agent })
console.log(r3.text.split('\n').slice(1, 3).join('\n'))

console.log('\n=== 4. 空查询（应列出全部，按 usage 排序）===')
console.log((await search.execute({ query: '' }, { agent })).text.split('\n').slice(1, 5).join('\n'))
EOF
