{"command":"timeout 40 powershell.exe -NoProfile -Command "
\$ErrorActionPreference='Continue'
try {
  \$out = ('protocol=https' + [char]10 + 'host=github.com' + [char]10 + [char]10) | git -c credential.interactive=false credential fill 2>&1
  \$p = \$out | Where-Object { ([string]\$_).StartsWith('password=') }
  \$u = \$out | Where-Object { ([string]\$_).StartsWith('username=') }
  if (\$p) {
    \$tok = ([string]\$p).Substring(9)
    'TOKEN  : GOT (length ' + \$tok.Length + ')'
    if (\$u) { 'USER   : ' + ([string]\$u).Substring(9) }
    \$h = @{ Authorization = 'token ' + \$tok; 'User-Agent' = 'dsh-agent'; Accept = 'application/vnd.github+json' }
    \$me = Invoke-RestMethod 'https://api.github.com/user' -Headers \$h -TimeoutSec 20
    'API OK : ' + \$me.login + '  public_repos=' + \$me.public_repos
  } else {
    'TOKEN  : NONE'
    (\$out | Select-Object -First 3) -join ' | '
  }
} catch { 'ERR: ' + \$_.Exception.Message }
" 2>&1 | head -8"}

