{"command":"cat > "$USERPROFILE/.dsh/_tmp-gh-cred.ps1" <<'PS1'
$ErrorActionPreference = 'Continue'
$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = 'git'
$psi.Arguments = '-c credential.interactive=false credential fill'
$psi.RedirectStandardInput = $true
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
$psi.UseShellExecute = $false
$psi.CreateNoWindow = $true
$proc = [System.Diagnostics.Process]::Start($psi)
$proc.StandardInput.Write("protocol=https`nhost=github.com`n`n")
$proc.StandardInput.Close()
$out = $proc.StandardOutput.ReadToEnd()
$err = $proc.StandardError.ReadToEnd()
$proc.WaitForExit(25000) | Out-Null

$tok = $null
foreach ($line in ($out -split "`n")) {
  if ($line.StartsWith('password=')) { $tok = $line.Substring(9).Trim() }
}
if ($null -eq $tok -or $tok.Length -eq 0) {
  'TOKEN: NONE'
  $keys = ($out -split "`n") | Where-Object { $_ } | ForEach-Object { ($_ -split '=')[0] }
  if ($keys) { 'fields returned: ' + ($keys -join ',') }
  if ($err) { 'stderr: ' + (($err -split "`n") | Where-Object { $_ } | Select-Object -First 1) }
  exit 0
}
'TOKEN: GOT (length ' + $tok.Length + ')'
$h = @{ Authorization = 'token ' + $tok; 'User-Agent' = 'dsh-agent'; Accept = 'application/vnd.github+json' }
try {
  $me = Invoke-RestMethod 'https://api.github.com/user' -Headers $h -TimeoutSec 20
  'API OK: login=' + $me.login + '  name=' + $me.name
} catch { 'API ERR: ' + $_.Exception.Message }
PS1
timeout 60 powershell.exe -NoProfile -ExecutionPolicy Bypass -File "C:\Users\27063\.dsh\_tmp-gh-cred.ps1" 2>&1 | head -8; rm -f "$USERPROFILE/.dsh/_tmp-gh-cred.ps1""}

