$ProgressPreference = 'SilentlyContinue'
$h = @{ 'User-Agent' = 'dsh-agent'; Accept = 'application/vnd.github+json' }
$repos = @('liustack/modlens','Anionex/dsh-vision-toolkit','1692775560/dsh-Mimir-Academic-research','Miaotofu01/Study-Mate')
$dir = 'C:\Users\27063\.dsh\storages\community-readmes'
foreach ($r in $repos) {
  $slug = $r -replace '/','__'
  try {
    $repo = Invoke-RestMethod ('https://api.github.com/repos/' + $r) -Headers $h -TimeoutSec 25
    '{0,-44} {1,6}*  {2,-10} {3}' -f $r, $repo.stargazers_count, [string]$repo.language, [string]$repo.license.spdx_id
    try {
      $rd = Invoke-RestMethod ('https://api.github.com/repos/' + $r + '/readme') -Headers $h -TimeoutSec 25
      $txt = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($rd.content -replace "`n", '')))
      [IO.File]::WriteAllText((Join-Path $dir ($slug + '.README.md')), $txt, (New-Object Text.UTF8Encoding($false)))
    } catch { '   (no readme)' }
  } catch { 'FAIL ' + $r + ' :: ' + $_.Exception.Message }
